const std = @import("std");

fn dfs(graph: [][5]u8, node: u8, visited: []bool) void {
    visited[node] = true;
    std.debug.print("{} ", .{node});
    for (0..5) |neighbor| {
        if (graph[node][neighbor] == 1 and !visited[neighbor]) {
            dfs(graph, @intCast(neighbor), visited);
        }
    }
}

pub fn main() !void {
    var graph = [_][5]u8{
        [_]u8{ 0, 1, 1, 0, 0 },
        [_]u8{ 1, 0, 0, 1, 0 },
        [_]u8{ 1, 0, 0, 1, 1 },
        [_]u8{ 0, 1, 1, 0, 0 },
        [_]u8{ 0, 0, 1, 0, 0 },
    };
    var visited = [_]bool{false} ** 5;
    dfs(&graph, 0, &visited);
    std.debug.print("\n", .{});
}
